192	    /**
193	     * 检查是否为允许的扩展名
194	     *
195	     * @param {string} filename - 文件名
196	     * @returns {boolean} - 是否允许
197	     */
198	    isAllowedExtension(filename) {
199	        const ext = path.extname(filename).toLowerCase();
200	        return this.allowedExtensions.includes(ext);
201	    }
202	}
203	
204	/**
205	 * 清理过期的临时文件
206	 *
207	 * @param {string} baseDir - 基础目录
208	 * @param {number} maxAgeMs - 最大存活时间（毫秒），默认 24 小时
209	 */
210	function cleanupExpiredFiles(baseDir, maxAgeMs = 24 * 60 * 60 * 1000) {
211	    const now = Date.now();
212	
213	    if (!fs.existsSync(baseDir)) {
214	        return;
215	    }
216	
217	    const entries = fs.readdirSync(baseDir, { withFileTypes: true });
218	
219	    for (const entry of entries) {
220	        const fullPath = path.join(baseDir, entry.name);
221	        const stat = fs.statSync(fullPath);
222	
223	        if (now - stat.mtimeMs > maxAgeMs) {
224	            if (entry.isDirectory()) {
225	                fs.rmSync(fullPath, { recursive: true });
226	                console.log("[Cleanup] Cleaned up directory: ${fullPath}");
227	            } else {
228	                fs.unlinkSync(fullPath);
229	                console.log("[Cleanup] Cleaned up file: ${fullPath}");
230	            }
231	        }
232	    }
233	}
234	
235	/**
236	 * 构建安全的 Claude CLI 参数数组
237	 * 使用参数数组而非字符串拼接，防止命令注入
238	 *
239	 * @param {Object} options - 选项
240	 * @returns {string[]} - 参数数组
241	 */
242	function buildClaudeArgs(options) {
243	    // 支持通过环境变量 CLAUDE_CODE_PATH 指定 claude 命令的完整路径
244	    // 如果没有设置，尝试自动检测
245	    let claudeCommand = process.env.CLAUDE_CODE_PATH;
246	
247	    if (!claudeCommand) {
248	        // 尝试常见的安装位置
249	        const path = require('path');
250	        const fs = require('fs');
251	
252	        const possiblePaths = [
253	            // Windows npm 全局安装位置
254	            path.join(process.env.APPDATA || '', 'npm', 'claude.cmd'),
255	            path.join(process.env.APPDATA || '', 'npm', 'claude'),
256	            // 用户目录下的 .claude
257	            path.join(process.env.USERPROFILE || '', '.claude', 'bin', 'claude.cmd'),
258	            path.join(process.env.USERPROFILE || '', '.claude', 'bin', 'claude'),
259	            // Linux/macOS 常见位置
260	            '/usr/local/bin/claude',
261	            '/usr/bin/claude',
262	            path.join(process.env.HOME || '', '.local', 'bin', 'claude')
263	        ];
264	
265	        for (const p of possiblePaths) {
266	            if (p && fs.existsSync(p)) {
267	                claudeCommand = p;
268	                console.log("[buildClaudeArgs] 自动检测到 Claude CLI: ${p}");
269	                break;
270	            }
271	        }
272	    }
273	
274	    // 如果还是找不到，使用默认值（让系统从 PATH 中查找）
275	    if (!claudeCommand) {
276	        claudeCommand = 'claude';
277	        console.log('[buildClaudeArgs] 使用默认 claude 命令，请确保在 PATH 中');
278	    }
279	
280	    const args = [claudeCommand, 'code', '-p'];
281	
282	    // 输出格式
283	    args.push('--output-format', options.outputFormat || 'stream-json');
284	
285	    // 详细模式
286	    if (options.verbose) {
287	        args.push('--verbose');
288	    }
289	
290	    // 危险标志（生产环境应该移除）
291	    if (options.dangerouslySkipPermissions) {
292	        args.push('--dangerously-skip-permissions');
293	    }
294	
295	    // 会话ID（新会话）
296	    if (options.sessionId && !options.resume) {
297	        // 验证 sessionId 格式
298	        if (!isValidSessionId(options.sessionId)) {
299	            throw new Error("Invalid session ID format: ${options.sessionId}");
300	        }
301	        args.push('--session-id', options.sessionId);
302	    }
303	
304	    // 恢复会话
305	    if (options.resume && options.sessionId) {
306	        if (!isValidSessionId(options.sessionId)) {
307	            throw new Error("Invalid session ID format: ${options.sessionId}");
308	        }
309	        args.push('--resume', options.sessionId);
310	    }
311	
312	    // Skill 目录
313	    // 注意：skillDir 应该来自 SafeZipExtractor，已经过安全验证
314	    // 这里不再重复验证绝对路径，因为 SafeZipExtractor 产生的路径是可信的
315	    if (options.skillDir) {
316	        // 确保 skillDir 存在且是目录
317	        if (fs.existsSync(options.skillDir)) {
318	            args.push('--add-dir', options.skillDir);
319	        } else {
320	            throw new Error("Skill directory does not exist: ${options.skillDir}");
321	        }
322	    }
323	
324	    return args;
325	}
326	
